/**
 * The permission catalogue: every key the API actually enforces, grouped the way an
 * administrator thinks about them rather than the way they are named.
 *
 * Generated by reading every `requirePermission(context, '...')` call and every
 * `context.permissions.has('...')` check in `apps/api/src`, not invented. A key appears here only
 * because some service already refuses a request without it — the Access Control UI can offer
 * exactly what the backend enforces and nothing it doesn't.
 *
 * `*` is deliberately absent: it is the tenant wildcard `ORG_ADMIN` carries, not a capability an
 * administrator composes into a custom role. `assertGrantable` (`RbacService`) still rejects a
 * caller who tries to grant it anyway; this list just never offers it as a checkbox.
 */
export type PermissionCatalogueEntry = {
  key: string;
  label: string;
  module: string;
};

