export const PERMISSION_KEYS = new Set(PERMISSION_CATALOGUE.map((entry) => entry.key));

/** The catalogue grouped by module, in catalogue order, for a grouped picker UI. */
export function groupPermissionCatalogue(): Array<{
  module: string;
  entries: PermissionCatalogueEntry[];
}> {
  const groups = new Map<string, PermissionCatalogueEntry[]>();
  for (const entry of PERMISSION_CATALOGUE) {
    const list = groups.get(entry.module) ?? [];
    list.push(entry);
    groups.set(entry.module, list);
  }
  return [...groups.entries()].map(([module, entries]) => ({ module, entries }));
}

// --- Role and member management, matching what UsersController actually accepts -----------------

export const roleWithPermissionsSchema = z.object({
  id: z.string().uuid(),
  organizationId: z.string().uuid().nullable(),
  code: z.string(),
  name: z.string(),
  description: z.string().nullable().optional(),
  scope: roleScopeSchema,
  branchId: z.string().uuid().nullable(),
  isSystem: z.boolean(),
  permissions: z.array(z.object({ permission: z.object({ key: z.string() }) })),
});
export type RoleWithPermissions = z.infer<typeof roleWithPermissionsSchema>;

export const memberRoleSchema = z.object({
  userRoleId: z.string().uuid(),
  id: z.string().uuid(),
  code: z.string(),
  name: z.string(),
  scope: roleScopeSchema,
  branchId: z.string().uuid().nullable(),
});

export const organizationMemberSchema = z.object({
  userId: z.string().uuid(),
  email: z.string(),
  displayName: z.string(),
  isActive: z.boolean(),
  joinedAt: z.string(),
  roles: z.array(memberRoleSchema),
});
export type OrganizationMember = z.infer<typeof organizationMemberSchema>;

function parseList<T>(schema: z.ZodType<T>, payload: unknown): T[] | null {
  const items =
    Array.isArray(payload) || payload === null || payload === undefined
      ? payload
      : ((payload as { items?: unknown }).items ?? payload);
  const result = z.array(schema).safeParse(items);
  return result.success ? result.data : null;
}

export function parseRoleList(payload: unknown): RoleWithPermissions[] | null {
  return parseList(roleWithPermissionsSchema, payload);
}

export function parseMemberList(payload: unknown): OrganizationMember[] | null {
  return parseList(organizationMemberSchema, payload);
}

/**
 * Where an employee stands on having a login of their own.
 *
 * An employee record and a login are separate things in this system, and the gap between them is
 * a real state an administrator has to be able to see and act on — not an error. These are the
 * four positions an employee can be in.
 */
export const EMPLOYEE_ACCESS_CODE_STATES = [
  /** Employee record exists, nobody has started giving them access. */
  'NO_ACCOUNT',
  /** A code is outstanding and still valid. */
  'CODE_ISSUED',
  /** A code was issued but its window has passed; issuing a new one is the way forward. */
  'CODE_EXPIRED',
  /** A login exists and is attached. They can sign in. */
  'ACTIVE',
] as const;

export type EmployeeAccessCodeState = (typeof EMPLOYEE_ACCESS_CODE_STATES)[number];

export const employeeAccessCodeStatusSchema = z.object({
  state: z.enum(EMPLOYEE_ACCESS_CODE_STATES),
  /** When the outstanding code stops working. Null unless one is outstanding. */
  expiresAt: z.string().nullable(),
  issuedAt: z.string().nullable(),
});

export type EmployeeAccessCodeStatus = z.infer<typeof employeeAccessCodeStatusSchema>;

/** The plaintext code, returned by the one response that creates it and never again. */
export const issuedAccessCodeSchema = z.object({
  code: z.string(),
  expiresAt: z.string(),
});

export type IssuedAccessCode = z.infer<typeof issuedAccessCodeSchema>;

/**
 * What an employee is shown after their code checks out, before they choose a password.
 *
 * Deliberately thin: enough for them to recognise the organization and themselves, and nothing
 * that would make a valid code worth harvesting for the information it reveals.
 */
export const accessCodePreviewSchema = z.object({
  organizationName: z.string(),
  employeeName: z.string(),
  employeeNumber: z.string(),
});

export type AccessCodePreview = z.infer<typeof accessCodePreviewSchema>;

export function parseAccessCodeStatus(payload: unknown): EmployeeAccessCodeStatus | null {
  const result = employeeAccessCodeStatusSchema.safeParse(payload);
  return result.success ? result.data : null;
}

export function parseAccessCodePreview(payload: unknown): AccessCodePreview | null {
  const result = accessCodePreviewSchema.safeParse(payload);
  return result.success ? result.data : null;
}
